#pragma once

// Plugins linked into the executable (GVIEW_STATIC_PLUGINS, used by the WebAssembly build where shared libraries can
// not be loaded at runtime). The tables are generated by CMake (cmake/StaticPlugins.cpp.in) from the plugins that are
// part of the build and are defined in the GView executable; GViewCore only looks the entry points up by name instead
// of loading lib<Name>.tpl / lib<Name>.gpl.

#ifdef GVIEW_STATIC_PLUGINS

#    include "GView.hpp"

#    include <span>

namespace GView::StaticPlugins
{
struct TypePlugin {
    std::string_view name; // the name of the [Type.<name>] section
    bool (*fnValidate)(const AppCUI::Utils::BufferView& buf, const std::string_view& extension);
    TypeInterface* (*fnCreateInstance)();
    bool (*fnPopulateWindow)(Reference<GView::View::WindowInterface> win);
    void (*fnUpdateSettings)(AppCUI::Utils::IniSection sect);
    void (*fnRegisterPlugin)(Reference<GView::PluginRegistry> registry); // static metadata (HDF vocabulary)
};

struct GenericPlugin {
    std::string_view name; // the name of the [Generic.<name>] section
    bool (*fnRun)(const std::string_view command, Reference<GView::Object> currentObject);
    void (*fnUpdateSettings)(AppCUI::Utils::IniSection sect);
    void (*fnRegisterPlugin)(Reference<GView::PluginRegistry> registry); // static metadata (HDF vocabulary)
};

// generated (see cmake/StaticPlugins.cpp.in)
std::span<const TypePlugin> GetTypePlugins();
std::span<const GenericPlugin> GetGenericPlugins();

inline const TypePlugin* FindTypePlugin(std::string_view name)
{
    for (const auto& p : GetTypePlugins())
        if (p.name == name)
            return &p;
    return nullptr;
}
inline const GenericPlugin* FindGenericPlugin(std::string_view name)
{
    for (const auto& p : GetGenericPlugins())
        if (p.name == name)
            return &p;
    return nullptr;
}
} // namespace GView::StaticPlugins

#endif // GVIEW_STATIC_PLUGINS
